create temporary table w4d3_runtime_baseline (
  station_count bigint not null,
  snapshot_count bigint not null,
  snapshot_station_count bigint not null
) on commit drop;

insert into w4d3_runtime_baseline (
  station_count,
  snapshot_count,
  snapshot_station_count
)
select
  (select count(*) from public.stations),
  (select count(*) from public.daily_water_snapshots),
  (
    select count(distinct station_id)
    from public.daily_water_snapshots
  );

do $$
declare
  baseline record;
begin
  select *
    into baseline
  from w4d3_runtime_baseline;

  if baseline.station_count <> 27 then
    raise exception
      'W4D-3 expected 27 station rows before import, found %',
      baseline.station_count;
  end if;

  if baseline.snapshot_count < 178 then
    raise exception
      'W4D-3 expected at least 178 snapshots before import, found %',
      baseline.snapshot_count;
  end if;

  if baseline.snapshot_station_count <> 23 then
    raise exception
      'W4D-3 expected 23 distinct snapshot station ids, found %',
      baseline.snapshot_station_count;
  end if;

  if not exists (
    select 1
    from public.water_bodies
    where canonical_key = 'ro-danube'
      and type = 'river'
      and country_code = 'RO'
  ) then
    raise exception 'W4D-3 requires the canonical Romania water identity migration.';
  end if;
end;
$$;

