do $w4d3_split$
begin
  if (select count(*) from w4d3_reservoirs_source) <> 1933 then
    raise exception 'Expected 1933 audited reservoirs';
  end if;
end
$w4d3_split$;

do $w4d3_split$
declare
  duplicate_source_identity_count bigint;
  invalid_raw_payload_count bigint;
begin
  select count(*)
    into duplicate_source_identity_count
  from (
    select
      btrim(source),
      upper(btrim(country_code)),
      btrim(source_asset_id)
    from w4d3_reservoirs_source
    group by
      btrim(source),
      upper(btrim(country_code)),
      btrim(source_asset_id)
    having count(*) > 1
  ) as duplicates;

  if duplicate_source_identity_count <> 0 then
    raise exception 'W4D-3 duplicate reservoir source identity.';
  end if;

  select count(*)
    into invalid_raw_payload_count
  from w4d3_reservoirs_source
  where jsonb_typeof(raw_payload_json::jsonb) <> 'object';

  if invalid_raw_payload_count <> 0 then
    raise exception 'W4D-3 reservoir raw payload must be a JSON object.';
  end if;
end
$w4d3_split$;

insert into public.reservoirs as target (
  source,
  country_code,
  asset_type,
  source_asset_id,
  source_record_number,
  source_record_fingerprint,
  source_numeric_id,
  national_lake_code,
  name,
  alternative_name,
  name_en,
  source_river_name,
  source_main_river_name,
  resolved_river_name,
  river_resolution_status,
  county,
  basin_code,
  basin_name,
  latitude,
  longitude,
  surface_area_km2,
  perimeter_km,
  volume_million_m3,
  flood_attenuation_volume_million_m3,
  dam_height_m,
  mean_depth_m,
  elevation_m,
  risk_index,
  importance_class,
  importance_category,
  owner,
  reservoir_type,
  dam_type,
  commissioned_year,
  hydropower_use,
  fishery_use,
  water_supply_use,
  recreation_use,
  match_key,
  canonicalization_status,
  map_eligible,
  raw_payload
)
select
  btrim(source),
  upper(btrim(country_code)),
  btrim(asset_type),
  btrim(source_asset_id),
  btrim(source_record_number)::integer,
  lower(btrim(source_record_fingerprint)),
  btrim(source_numeric_id)::integer,
  btrim(national_lake_code),
  btrim(name),
  nullif(btrim(alternative_name), ''),
  nullif(btrim(name_en), ''),
  nullif(btrim(source_river_name), ''),
  nullif(btrim(source_main_river_name), ''),
  nullif(btrim(resolved_river_name), ''),
  btrim(river_resolution_status),
  nullif(btrim(county), ''),
  nullif(btrim(basin_code), ''),
  nullif(btrim(basin_name), ''),
  btrim(latitude)::double precision,
  btrim(longitude)::double precision,
  nullif(btrim(surface_area_km2), '')::numeric,
  nullif(btrim(perimeter_km), '')::numeric,
  nullif(btrim(volume_million_m3), '')::numeric,
  nullif(btrim(flood_attenuation_volume_million_m3), '')::numeric,
  nullif(btrim(dam_height_m), '')::numeric,
  nullif(btrim(mean_depth_m), '')::numeric,
  nullif(btrim(elevation_m), '')::numeric,
  nullif(btrim(risk_index), '')::numeric,
  nullif(btrim(importance_class), ''),
  nullif(btrim(importance_category), ''),
  nullif(btrim(owner), ''),
  nullif(btrim(reservoir_type), ''),
  nullif(btrim(dam_type), ''),
  nullif(btrim(commissioned_year), ''),
  nullif(btrim(hydropower_use), ''),
  nullif(btrim(fishery_use), ''),
  nullif(btrim(water_supply_use), ''),
  nullif(btrim(recreation_use), ''),
  nullif(btrim(match_key), ''),
  btrim(canonicalization_status),
  case lower(btrim(map_eligible))
    when 'true' then true
    when 'false' then false
    else null
  end,
  raw_payload_json::jsonb
from w4d3_reservoirs_source
on conflict (source, country_code, source_asset_id)
do update set
  source_record_number = excluded.source_record_number,
  source_record_fingerprint = excluded.source_record_fingerprint,
  source_numeric_id = excluded.source_numeric_id,
  national_lake_code = excluded.national_lake_code,
  name = excluded.name,
  alternative_name = excluded.alternative_name,
  name_en = excluded.name_en,
  source_river_name = excluded.source_river_name,
  source_main_river_name = excluded.source_main_river_name,
  resolved_river_name = excluded.resolved_river_name,
  river_resolution_status = excluded.river_resolution_status,
  county = excluded.county,
  basin_code = excluded.basin_code,
  basin_name = excluded.basin_name,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  surface_area_km2 = excluded.surface_area_km2,
  perimeter_km = excluded.perimeter_km,
  volume_million_m3 = excluded.volume_million_m3,
  flood_attenuation_volume_million_m3 =
    excluded.flood_attenuation_volume_million_m3,
  dam_height_m = excluded.dam_height_m,
  mean_depth_m = excluded.mean_depth_m,
  elevation_m = excluded.elevation_m,
  risk_index = excluded.risk_index,
  importance_class = excluded.importance_class,
  importance_category = excluded.importance_category,
  owner = excluded.owner,
  reservoir_type = excluded.reservoir_type,
  dam_type = excluded.dam_type,
  commissioned_year = excluded.commissioned_year,
  hydropower_use = excluded.hydropower_use,
  fishery_use = excluded.fishery_use,
  water_supply_use = excluded.water_supply_use,
  recreation_use = excluded.recreation_use,
  match_key = excluded.match_key,
  canonicalization_status = excluded.canonicalization_status,
  map_eligible = excluded.map_eligible,
  raw_payload = excluded.raw_payload
where (
  to_jsonb(target)
    - array['id', 'created_at', 'updated_at', 'water_body_id']
) is distinct from (
  to_jsonb(excluded)
    - array['id', 'created_at', 'updated_at', 'water_body_id']
);


comment on table public.reservoirs is
  'Canonical reservoir catalog. Romania W4D-3 imported 1933 audited ANAR rows.';


commit;
